const lc=(a,w=640,h=220)=>{const mn=Math.min(...a,0),mx=Math.max(...a),x=i=>i/(a.length-1)*w,y=v=>h-8-(v-mn)/(mx-mn)*(h-16);return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Cumulative PnL"><line x1="0" x2="${w}" y1="${y(0)}" y2="${y(0)}" stroke="#334" stroke-dasharray="4"/><polyline fill="none" stroke="#F0C560" stroke-width="2.5" points="${a.map((v,i)=>x(i)+","+y(v)).join(" ")}"/></svg>`};
const mb=a=>{const m=Math.max(...a.map(x=>Math.abs(x[1])));return `<div class="mbars">${a.map(x=>`<div><i style="height:${Math.abs(x[1])/m*80+2}px;background:${x[1]<0?"#F87171":"#34D399"}"></i><small>${x[0].slice(0,3)}</small><small class="${x[1]<0?"dnr":"up"}">${x[1]}</small></div>`).join("")}</div>`};
