const donut=(p,l,sub,c="#34D399")=>`<div class="dc"><svg viewBox="0 0 100 100" role="img" aria-label="${l} ${p}%"><circle cx="50" cy="50" r="40" fill="none" stroke="#26314f" stroke-width="12"/><circle cx="50" cy="50" r="40" fill="none" stroke="${c}" stroke-width="12" stroke-linecap="round" stroke-dasharray="${(p*2.513).toFixed(1)} 251.3" transform="rotate(-90 50 50)"/><text x="50" y="56" text-anchor="middle" fill="#fff" font-size="17" font-weight="700">${p}%</text></svg><b>${l}</b><small>${sub}</small></div>`;
const split=(a,av,b,bv,ad,bd,ca="#34D399",cb="#F87171")=>{const t=av+bv;return `<div class="sb"><div class="bar"><i style="width:${av/t*100}%;background:${ca}"></i><i style="width:${bv/t*100}%;background:${cb}"></i></div><div class="lg"><span><s style="background:${ca}"></s>${a} <b style="color:${ca}">${ad}</b></span><span><s style="background:${cb}"></s>${b} <b style="color:${cb}">${bd}</b></span></div></div>`};
