const tbl=(h,r)=>`<div class="sc2"><table class="mt"><tr>${h.map(x=>`<th>${x}</th>`).join("")}</tr>${r.map(x=>`<tr>${x.map(y=>`<td class="${vc(y)}">${y||"–"}</td>`).join("")}</tr>`).join("")}</table></div>`;
