document.querySelectorAll("[data-t]").forEach(b=>b.onclick=()=>{document.querySelectorAll("[data-t]").forEach(x=>x.classList.toggle("on",x==b));const a=REPORTS[b.dataset.t];$("#rp").innerHTML=a.map(r=>`<article class="g"><span class="ph">${r.type}</span> <span class="ph">Placeholder</span><h3 style="margin-top:10px">${r.name}</h3><p class="mut">${r.market} · ${r.tf}</p><table>${r.rows.map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td></tr>`).join("")}</table><div class="btns">${cta("Request Live Demo")}</div></article>`).join("")});

document.querySelectorAll(".g,.tl .g").forEach(e=>e.classList.add("rv"));
const io=new IntersectionObserver(a=>a.forEach(x=>x.isIntersecting&&(x.target.classList.add("in"),io.unobserve(x.target))),{threshold:.12});document.querySelectorAll(".rv").forEach(e=>io.observe(e));
document.addEventListener("mousemove",e=>{const g=e.target.closest&&e.target.closest(".g");if(g){const r=g.getBoundingClientRect();g.style.setProperty("--x",e.clientX-r.left+"px");g.style.setProperty("--y",e.clientY-r.top+"px")}});



document.querySelectorAll("[data-pt]").forEach(b=>b.onclick=()=>{document.querySelectorAll("[data-pt]").forEach(x=>x.classList.toggle("on",x==b));$("#pa").hidden=b.dataset.pt!="a";$("#pb").hidden=b.dataset.pt!="b"});
document.querySelectorAll(".rv:not(.in)").forEach(e=>io.observe(e));

document.querySelectorAll("[data-ti]").forEach(b=>b.onclick=()=>{document.querySelectorAll("[data-ti]").forEach(x=>x.classList.toggle("on",x==b));$("#cd").textContent=TECH[b.dataset.ti][2]});
document.querySelectorAll("#sv article").forEach((a,i)=>a.dataset.c=CATS[i]);
document.querySelectorAll("[data-f]").forEach(b=>b.onclick=()=>{document.querySelectorAll("[data-f]").forEach(x=>x.classList.toggle("on",x==b));document.querySelectorAll("#sv article").forEach(a=>a.hidden=b.dataset.f!="all"&&a.dataset.c!=b.dataset.f)});
document.querySelectorAll(".vd").forEach(d=>d.onclick=()=>{if(d.querySelector("video"))return;const v=document.createElement("video");v.src=d.dataset.v;v.controls=true;v.autoplay=true;v.playsInline=true;v.onerror=()=>{v.remove();d.querySelector(".tag").textContent="Add the file "+d.dataset.v+" to play it here."};d.querySelector(".vp").appendChild(v)});
const cio=new IntersectionObserver(a=>a.forEach(x=>{if(!x.isIntersecting)return;cio.unobserve(x.target);const n=+x.target.dataset.n;let i=0;const t=setInterval(()=>{x.target.textContent=++i;if(i>=n)clearInterval(t)},120)}));document.querySelectorAll(".cnt").forEach(e=>cio.observe(e));
(()=>{const c=$("#hc"),v=$("#hv");if(!c)return;v.addEventListener("canplay",()=>v.classList.add("on"));const x=c.getContext("2d");let t=0;const p=k=>45*Math.sin(k*.31)+80*Math.sin(k*.113)+10*Math.sin(k*.7);const rs=()=>{c.width=c.offsetWidth;c.height=c.offsetHeight};rs();addEventListener("resize",rs);
(function d(){requestAnimationFrame(d);if(v.classList.contains("on"))return;x.clearRect(0,0,c.width,c.height);const k0=Math.floor(t/24);for(let i=0;i<c.width/24+2;i++){const k=k0+i,X=i*24-t%24,o=c.height/2+p(k),cl=c.height/2+p(k+1)+Math.sin(k*1.7)*14;x.strokeStyle=x.fillStyle=cl<o?"#22D3EE":"#8B5CF6";x.beginPath();x.moveTo(X,Math.min(o,cl)-14);x.lineTo(X,Math.max(o,cl)+14);x.stroke();x.fillRect(X-6,Math.min(o,cl),12,Math.abs(o-cl)+2)}t+=1.2})()})();

if(p=="indicators"){const sh=()=>{const i=IND.find(x=>"#"+x.id==location.hash);$("#det").innerHTML=i?indDetail(i):"";if(i)$("#det").scrollIntoView({behavior:"smooth"})};addEventListener("hashchange",sh);sh()}

document.body.insertAdjacentHTML("beforeend",`<a class="floatwa" href="${wl("Hi")}" target="_blank" rel="noopener noreferrer" aria-label="Chat on WhatsApp">WhatsApp</a>`);
const openForm=()=>{let m=document.getElementById("fmod");if(!m){m=document.createElement("div");m.id="fmod";m.innerHTML=`<div class="fbox"><button class="fx" aria-label="Close form">×</button><iframe src="${FE}" title="CK Trading inquiry form" frameborder="0" marginheight="0" marginwidth="0">Loading…</iframe></div>`;document.body.appendChild(m);m.onclick=ev=>{if(ev.target==m||ev.target.classList.contains("fx"))m.hidden=true}}m.hidden=false};
document.addEventListener("click",e=>{const a=e.target.closest&&e.target.closest("a[data-form]");if(a){e.preventDefault();openForm()}});
